WITH latest AS (SELECT * FROM customers QUALIFY RANK() OVER (PARTITION BY segment, country ORDER BY age DESC NULLS LAST) = 1) SELECT country, DATE_TRUNC('MONTH', signup_date) AS activity_month, DATE_TRUNC('QUARTER', signup_date) AS quarter_start, COUNT(CASE WHEN segment = 'Corporate' THEN 1 END) AS corporate_count, ROUND(AVG(credit_limit), 2) AS avg_credit_limit, COUNT_IF(country = 'JP') AS jp_events FROM latest GROUP BY country, DATE_TRUNC('MONTH', signup_date), DATE_TRUNC('QUARTER', signup_date) HAVING corporate_count < 1
